using UnityEngine;

[RequireComponent(typeof(MeshFilter), typeof(MeshRenderer))]
public class SimpleMeshCombiner : MonoBehaviour
{
    [ContextMenu("Combinar Malhas")]
    public void CombineMeshes()
    {
        MeshFilter[] meshFilters = GetComponentsInChildren<MeshFilter>();
        CombineInstance[] combine = new CombineInstance[meshFilters.Length - 1];
        int combineIndex = 0;
        MeshFilter parentFilter = GetComponent<MeshFilter>();

        for (int i = 0; i < meshFilters.Length; i++)
        {
            if (meshFilters[i] == parentFilter) continue;
            combine[combineIndex].mesh = meshFilters[i].sharedMesh;
            combine[combineIndex].transform = transform.worldToLocalMatrix * meshFilters[i].transform.localToWorldMatrix;
            meshFilters[i].gameObject.SetActive(false);
            combineIndex++;
        }

        Mesh finalMesh = new Mesh();
        finalMesh.indexFormat = UnityEngine.Rendering.IndexFormat.UInt32;
        finalMesh.CombineMeshes(combine, true, true);
        parentFilter.sharedMesh = finalMesh;
        gameObject.SetActive(true);
    }
}

using UnityEngine;
using UnityEngine.Rendering;

public class DynamicGpuPerformanceManager : MonoBehaviour
{
    [Header("Metas de Desempenho")]
    [SerializeField] private float targetFrameTimeMs = 16.67f;
    [SerializeField] private float toleranceMs = 1.5f;

    [Header("Limites de Escala de Renderização")]
    [Range(0.5f, 1.0f)] [SerializeField] private float minRenderScale = 0.65f;
    [Range(0.5f, 1.0f)] [SerializeField] private float maxRenderScale = 1.0f;
    [SerializeField] private float scaleStep = 0.05f;
    [SerializeField] private float adjustmentInterval = 0.5f;

    private float currentScale = 1.0f;
    private float timer = 0f;
    private FrameTiming[] timings = new FrameTiming[1];

    private void Start()
    {
        currentScale = maxRenderScale;
        ScalableBufferManager.ResizeBuffers(currentScale, currentScale);
        QualitySettings.shadowCascades = 2;
        QualitySettings.shadowDistance = Mathf.Min(QualitySettings.shadowDistance, 40f);
    }

    private void Update()
    {
        timer += Time.unscaledDeltaTime;
        if (timer < adjustmentInterval) return;
        timer = 0f;

        FrameTimingManager.CaptureFrameTimings();
        uint captured = FrameTimingManager.GetLatestTimings(1, timings);

        float gpuTime = captured > 0 ? (float)timings[0].gpuFrameTime : (Time.unscaledDeltaTime * 1000f);

        if (gpuTime > (targetFrameTimeMs + toleranceMs) && currentScale > minRenderScale)
        {
            currentScale = Mathf.Max(minRenderScale, currentScale - scaleStep);
            ScalableBufferManager.ResizeBuffers(currentScale, currentScale);
        }
        else if (gpuTime < (targetFrameTimeMs - toleranceMs) && currentScale < maxRenderScale)
        {
            currentScale = Mathf.Min(maxRenderScale, currentScale + scaleStep);
            ScalableBufferManager.ResizeBuffers(currentScale, currentScale);
        }
    }
}

using UnityEngine;
using System.Collections.Generic;

public class ProjectilePoolManager : MonoBehaviour
{
    [SerializeField] private GameObject projectilePrefab;
    [SerializeField] private int initialPoolSize = 100;

    private readonly Queue<GameObject> _pool = new Queue<GameObject>();

    private void Awake()
    {
        for (int i = 0; i < initialPoolSize; i++)
        {
            CreateNewInstance();
        }
    }

    private GameObject CreateNewInstance()
    {
        GameObject instance = Instantiate(projectilePrefab, transform);
        instance.SetActive(false);
        _pool.Enqueue(instance);
        return instance;
    }

    public GameObject Spawn(Vector3 position, Quaternion rotation)
    {
        GameObject obj = _pool.Count > 0 ? _pool.Dequeue() : CreateNewInstance();
        obj.transform.position = position;
        obj.transform.rotation = rotation;
        obj.SetActive(true);
        return obj;
    }

    public void Despawn(GameObject obj)
    {
        obj.SetActive(false);
        _pool.Enqueue(obj);
    }
}

using System;
using System.Text;
using UnityEngine;

namespace PerformanceAdvisor.StressTest
{
    public class StressTestScene : MonoBehaviour
    {
        public bool stressGc = false;
        public bool stressCpu = false;
        public bool stressDraw = false;

        public GameObject testPrefab;

        [Range(1, 20)]
        public float spawnRadius = 10f;

        [Range(1, 50)]
        public int cubesPerFrame = 1;

        public bool useUniqueMaterials = false;

        [Range(1, 512)]
        public int cpuScansPerFrame = 1;

        public int emptyObjects = 0;
        public int gcConcatIterations = 1000;
        public int gcArrayAllocs = 0;
        public int overdrawLayers = 0;
        public Material overdrawMaterial;

        [Range(0, 2000)]
        public int prepopulateCount = 0;

        private StringBuilder _cachedStringBuilder;
        private MaterialPropertyBlock _propertyBlock;
        private static readonly int ColorPropertyId = Shader.PropertyToID("_Color");

        private void Awake()
        {
            _cachedStringBuilder = new StringBuilder(4096);
            _propertyBlock = new MaterialPropertyBlock();
        }

        private void Start()
        {
            if (prepopulateCount > 0 && testPrefab != null)
            {
                for (int i = 0; i < prepopulateCount; i++)
                {
                    SpawnOne();
                }
            }

            for (int i = 0; i < emptyObjects; i++)
            {
                new GameObject(string.Concat("Empty_", i));
            }

            if (overdrawLayers > 0 && overdrawMaterial != null)
            {
                BuildOverdrawLayers();
            }
        }

        private void BuildOverdrawLayers()
        {
            Camera cam = Camera.main;
            if (cam == null) return;
            float halfFov = cam.fieldOfView * 0.5f * Mathf.Deg2Rad;
            for (int i = 0; i < overdrawLayers; i++)
            {
                float d = cam.nearClipPlane + 0.05f + i * 0.001f;
                float h = 2f * d * Mathf.Tan(halfFov) * 1.1f;
                var quad = GameObject.CreatePrimitive(PrimitiveType.Quad);
                Destroy(quad.GetComponent<Collider>());
                quad.name = string.Concat("Overdraw_", i);
                quad.transform.SetParent(cam.transform, false);
                quad.transform.localPosition = new Vector3(0f, 0f, d);
                quad.transform.localScale = new Vector3(h * cam.aspect, h, 1f);
                quad.GetComponent<Renderer>().sharedMaterial = overdrawMaterial;
            }
        }

        private void Update()
        {
            if (stressGc)
            {
                _cachedStringBuilder.Clear();
                for (int i = 0; i < gcConcatIterations; i++)
                {
                    _cachedStringBuilder.Append(i);
                }
            }

            if (stressDraw && testPrefab != null)
            {
                int n = Mathf.Max(1, cubesPerFrame);
                for (int i = 0; i < n; i++)
                {
                    SpawnOne();
                }
            }
        }

        private void SpawnOne()
        {
            var clone = Instantiate(
                testPrefab,
                UnityEngine.Random.insideUnitSphere * spawnRadius,
                Quaternion.identity);

            if (useUniqueMaterials)
            {
                var renderer = clone.GetComponent<Renderer>();
                if (renderer != null)
